// équivalent indicatif dans la monnaie du pays de commande (aucun pour les pays du franc CFA)
function enDevise(xof) {
  const p = pays() || P.paysCommande.FR, t = P.taux[p.devise];
  if (!t || p.devise === 'XOF') return '';
  const v = xof / t;
  try { return v.toLocaleString('fr-FR', { style: 'currency', currency: p.devise, maximumFractionDigits: v >= 1000 ? 0 : 2 }); } catch (e) { return Math.round(v) + ' ' + p.devise; }
}
const equiv = (xof) => { const s = enDevise(xof); return s ? '≈ ' + s : ''; };
function noteDevise() {
  const p = pays() || P.paysCommande.FR;
  if (p.devise === 'XOF' || !P.taux[p.devise]) return '';
  return 'Équivalent ' + p.devise + ' indicatif (' + (p.devise === 'EUR' ? 'parité fixe 1 € = 655,957 FCFA' : 'taux du ' + P.tauxDate + ' : 1 ' + p.devise + ' ≈ ' + (Math.round(P.taux[p.devise] * 100) / 100).toLocaleString('fr-FR') + ' FCFA') + ').';
}
